// Accepts three shapes:
//  1. Daweuchi router forward: {id, topic, source, payload: <GengoWatcher envelope>}
//  2. Raw GengoWatcher outbound envelope: {event_id, event_type, created_at, payload}
//  3. Either of the above wrapped in the n8n Webhook item ({headers, params, query, body}).
// Pure JS only: n8n 2.x blocks environment access and expression evaluation in Code nodes.
const raw = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const envelope = (raw.payload && typeof raw.payload === 'object' && raw.payload.event_type)
  ? raw.payload
  : raw;
const p = (envelope.payload && typeof envelope.payload === 'object') ? envelope.payload : {};

const eventType = String(envelope.event_type || '');
const collectionId = String(p.collection_id || p.id || p.job_id || '');
const title = String(p.title || ('Gengo #' + collectionId));
const langPair = String(
  p.lang_pair ||
  ((p.lc_src && p.lc_tgt) ? (String(p.lc_src).toUpperCase() + '->' + String(p.lc_tgt).toUpperCase()) : 'JA->EN')
);
const reward = Number(p.reward || 0);
const unitCount = Number(p.unit_count || p.word_count || 0);
const secondsLeft = Number(p.seconds_left || p.accepted_seconds_left || 0);
const allottedSeconds = Number(p.allotted_seconds || 3600);
const expireTime = Number(p.expire_time || 0);
const deadlineEpoch = Number(
  p.deadline_epoch ||
  (expireTime > 1e10 ? expireTime / 1000 : expireTime) ||
  (secondsLeft > 0 ? Math.floor(Date.now() / 1000) + secondsLeft : 0)
);
const alertMin = Number(p.alert_minutes_before || 30);
const submitMin = Number(p.autosubmit_minutes_before || 15);
const iso = (epoch) => (epoch > 0 ? new Date(epoch * 1000).toISOString() : '');

// The approval token is minted by the "Generate Approval Token" Crypto node on
// job.accepted (CSPRNG) or by GengoWatcher (secrets.token_urlsafe). Never invent one
// here for later events: a token GengoWatcher does not know would break approvals.
const approvalToken = String(p.approval_token || '');
const workbenchUrl = String(p.workbench_url || p.url || ('https://gengo.com/t/workbench/' + collectionId));
const nextcloudUrl = String(p.nextcloud_url || 'https://files.daweuchi.com/apps/files/?dir=/Gengo/Active');
const formBaseUrl = 'https://n8n.daweuchi.com/form/gengo-approval';
// encodeURIComponent leaves "(" and ")" alone; escape them so Markdown [text](url)
// links in alert messages do not end early at the ")" of "Hold (Disable ...)".
const enc = (s) => encodeURIComponent(String(s)).replace(/\(/g, '%28').replace(/\)/g, '%29');
const formUrl = (token, decision) =>
  formBaseUrl + '?collection_id=' + enc(collectionId) +
  '&token=' + enc(token) + '&decision=' + enc(decision);
const validationErrors = Array.isArray(p.validation_errors) ? p.validation_errors : [];
// Counts only: comment text, terms and glossary hits never leave the PC.
const commentsCount = Number(p.comments_count || 0);
const uncertainTermsCount = Number(p.uncertain_terms_count || 0);
const glossaryWarningsCount = Number(p.glossary_warnings_count || 0);
const acceptanceSource = String(p.acceptance_source || '');
const newCommentsCount = Number(p.new_comments_count || 0);
const revisionCount = Number(p.revision_count || 0);

return {
  json: {
    eventType,
    eventId: String(envelope.event_id || raw.id || ''),
    collectionId,
    title,
    langPair,
    reward,
    unitCount,
    secondsLeft,
    allottedSeconds,
    deadlineEpoch,
    alertMin,
    submitMin,
    deadlineIso: iso(deadlineEpoch),
    alertAtIso: iso(deadlineEpoch - alertMin * 60),
    submitAtIso: iso(deadlineEpoch - submitMin * 60),
    approvalToken,
    workbenchUrl,
    nextcloudUrl,
    formBaseUrl,
    approveUrl: formUrl(approvalToken, 'Approve & Submit Now'),
    holdUrl: formUrl(approvalToken, 'Hold (Disable 15m Auto-Submit)'),
    reviewSummary: String(p.review_summary || ''),
    correctionsCount: Number(p.corrections_count || 0),
    segmentCount: Number(p.segment_count || 0),
    hasErrors: Number(p.has_errors || 0),
    validationErrorCount: validationErrors.length,
    requiresManualUpload: Boolean(p.requires_manual_upload),
    reviewFilePath: String(p.review_file_path || ''),
    submitReason: String(p.submit_reason || p.reason || ''),
    autoSubmitted: Boolean(p.auto_submitted),
    outcome: String(p.outcome || ''),
    archivedDir: String(p.archived_dir || ''),
    reason: String(p.reason || ''),
    state: String(p.state || ''),
    error: String(p.error || ''),
    errorType: String(p.error_type || ''),
    commentsCount,
    uncertainTermsCount,
    glossaryWarningsCount,
    acceptanceSource,
    newCommentsCount,
    revisionCount,
  },
};
